"""Receipt-backed stage04 source and temporal/accuracy registry."""
from pathlib import Path
import json,datetime
from zoneinfo import ZoneInfo
from stage02_io import write_json,digest
ROOT=Path(__file__).resolve().parents[1]
def register(root=ROOT):
 rows=[]
 for receipt in sorted((root/'data/raw/stage04').rglob('*.receipt.json')):
  d=json.loads(receipt.read_text());p=Path(str(receipt)[:-len('.receipt.json')]);assert digest(p)==d['sha256'];rel=str(p.relative_to(root));key='OSM' if '/osm/' in rel else 'Caltrans' if 'markings_' in rel or 'camutcd' in rel else 'CityGIS' if any(s in rel for s in ['/signals/','/bridges/','/metro_']) else 'research'
  rows.append({'dataset_group':key,'publisher':'OpenStreetMap contributors; extract by Geofabrik' if key=='OSM' else 'California Department of Transportation' if key=='Caltrans' else 'City of Los Angeles GIS / LADOT / Metro-derived service' if key=='CityGIS' else 'see URL','source_url':d['url'],'request_parameters':d.get('request_parameters',{}),'downloaded_at_utc':d['downloaded_at_utc'],'collection_year':None,'data_state_timestamp':'2026-10-20T20:23:47Z' if key=='OSM' else None,'content_update_date':None,'page_update_date':None,'http_last_modified':d.get('http_last_modified'),'coverage':'California extract; model clipped to Los Angeles city2025' if key=='OSM' else 'source-specific service extent retained in layer metadata','horizontal_crs':'EPSG4326' if key=='OSM' else 'EPSG3857 service native / EPSG4326 query output' if key=='CityGIS' else None,'horizontal_units':'degrees in source; meters after EPSG32611 transform' if key=='OSM' else 'native service meters / downloaded query degrees / project meters' if key=='CityGIS' else None,'vertical_datum':None,'vertical_units':None,'accuracy_m':None,'accuracy_status':'unknown; no survey precision inferred from timestamps/field names','license':'ODbL1.0' if key=='OSM' else 'published standard; Caltrans document terms' if key=='Caltrans' else 'public service access; redistribution permission not independently established','attribution':'© OpenStreetMap contributors; Geofabrik' if key=='OSM' else 'see publisher and URL','redistribution':'ODbL obligations apply to derivative transportation database' if key=='OSM' else 'review publisher terms before external redistribution','local_path':rel,'sha256':d['sha256'],'bytes':p.stat().st_size})
 write_json(root/'data/processed/stage04/source_registry.json',{'created_at':datetime.datetime.now(ZoneInfo('Asia/Singapore')).isoformat(),'files':rows,'time_policy':'mixed vintage; OSM edit times/database state != collection year. Census2025/USGS2023-24 DT bareearth mixed explicitly. No single-day city snapshot.','reused_source_registries':['data/processed/stage02/source_registry.json','docs/stage03_sources.md'],'do_not_use':['City bridge Under_Clearance/Over_Clearance unit undefined','OSM layer as a measured metric elevation','DTM as actual bridge deck','OSM raster tiles for bulk textures']});print('SOURCE_RECEIPTS_VERIFIED',len(rows),flush=True)
if __name__=='__main__':register()
